// https://p5js.org/reference/p5/createGraphics/

function initPoints() {
  let w = 100;
  let h = 100;
  for (let i = 0; i < 20; i++) {
    let x = random(w);
    let y = random(h);
    let z = random(w);
    points[i] = { x, y, z };
    // points[i] = createVector(random(width), random(height), random(width));
  }
}

function draw() {
  updateLayer();
  let w = layer.width;
  let h = layer.height;
  image(layer, 0, 0, width, height, 0, 0, w, h);
  // image(layer, 0, 0);
}
// https://p5js.org/reference/p5/image/
// image(img, x, y, [width], [height])
// image(img, dx, dy, dWidth, dHeight, sx, sy, [sWidth], [sHeight], [fit], [xAlign], [yAlign])

function updateLayer() {
  layer.loadPixels();
  let w = layer.width;
  let h = layer.height;
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) {
      let distances = [];
      for (let i = 0; i < points.length; i++) {
        let v = points[i];
        let z = frameCount % w;
        let d = dist(x, y, z, v.x, v.y, v.z);
        distances[i] = d;
      }
      let sorted = sort(distances);
      let r = map(sorted[0], 0, 150, 0, 255);
      let g = map(sorted[1], 0, 50, 255, 0);
      let b = map(sorted[2], 0, 200, 255, 0);
      let index = (x + y * w) * 4;
      layer.pixels[index + 0] = r;
      layer.pixels[index + 1] = g;
      layer.pixels[index + 2] = b;
      layer.pixels[index + 3] = 255;
    }
  }
  layer.updatePixels();
}

