function drawCloud(x, y, w, h) {

  noStroke();
  fill(255);

  beginShape();
  curveVertex(x - w / 2, y);
  curveVertex(x - w / 4, y - h / 2);
  curveVertex(x, y - h);
  curveVertex(x + w / 4, y - h / 2);
  curveVertex(x + w / 2, y);
  endShape();beginShape();
  curveVertex(x+50 - w / 2, y-25);
  curveVertex(x+50 - w / 4, y-25 - h / 4);
  curveVertex(x+50, y-25 - h/2);
  curveVertex(x+50 + w / 4, y-25 - h / 4);
  curveVertex(x+50 + w / 2, y-25);
  endShape();
}

