    this.leftArmY -= this.legRotateSpeed* 20

    // move right arm
    this.rightArmRotate -= this.legRotateSpeed
    this.rightArmY += this.legRotateSpeed* 10

    this.time += 1
    if(this.time > 40){
      this.time = 0
    }

  }
  display() {

    push();
    noStroke();
    translate(this.x, this.y);

    this.colorFill()

